import{_ as i,C as r,o,c as n,a0 as s,b as l,w as t,a as h,E as d,a1 as u}from"./chunks/framework.6sfUeJuU.js";const y=JSON.parse('{"title":"Chapter 02: Introduction & Setup","description":"","frontmatter":{},"headers":[],"relativePath":"junior/02-setup.md","filePath":"junior/02-setup.md"}'),c={name:"junior/02-setup.md"};function p(m,e,g,b,k,f){const a=r("Mermaid");return o(),n("div",null,[e[1]||(e[1]=s('<h1 id="chapter-02-introduction-setup" tabindex="-1">Chapter 02: Introduction &amp; Setup <a class="header-anchor" href="#chapter-02-introduction-setup" aria-label="Permalink to &quot;Chapter 02: Introduction &amp; Setup&quot;">​</a></h1><p>A master craftsman needs sharp tools. Let&#39;s set up your environment.</p><h2 id="_1-install-go-the-compiler" tabindex="-1">1. Install Go (The Compiler) <a class="header-anchor" href="#_1-install-go-the-compiler" aria-label="Permalink to &quot;1. Install Go (The Compiler)&quot;">​</a></h2><p>Go is a compiled language. You need the &quot;Compiler&quot; to turn your text code into a binary program that the computer understands.</p><ul><li><strong>Download</strong>: <a href="https://go.dev/dl/" target="_blank" rel="noreferrer">go.dev/dl</a></li><li><strong>Verify</strong>: Open your terminal (Command Prompt) and type:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span></code></pre></div>You should see something like <code>go version go1.21...</code>.</li></ul><h2 id="_2-the-code-editor-vs-code" tabindex="-1">2. The Code Editor (VS Code) <a class="header-anchor" href="#_2-the-code-editor-vs-code" aria-label="Permalink to &quot;2. The Code Editor (VS Code)&quot;">​</a></h2><p>We recommend <strong>Visual Studio Code (VS Code)</strong>. It is free and powerful.</p><ol><li>Download <a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">VS Code</a>.</li><li><strong>Crucial Step</strong>: Install the <strong>Go Extension</strong> by the Go Team at Google. <ul><li>Click the &quot;Extensions&quot; box on the left sidebar.</li><li>Search for &quot;Go&quot;.</li><li>Install the one with the blue Gopher icon.</li></ul></li></ol><h2 id="_3-the-commands-your-toolbar" tabindex="-1">3. The Commands (Your Toolbar) <a class="header-anchor" href="#_3-the-commands-your-toolbar" aria-label="Permalink to &quot;3. The Commands (Your Toolbar)&quot;">​</a></h2><p>You will use three main commands in your terminal:</p><h3 id="a-go-mod-init-name" tabindex="-1">A. <code>go mod init [name]</code> <a class="header-anchor" href="#a-go-mod-init-name" aria-label="Permalink to &quot;A. `go mod init [name]`&quot;">​</a></h3><p><strong>&quot;Initialize Project&quot;</strong> This creates a <code>go.mod</code> file. Think of it as the &quot;Passport&quot; for your project. It tells Go clearly who you are.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github.com/myname/myproject</span></span></code></pre></div><h3 id="b-go-run-main-go" tabindex="-1">B. <code>go run main.go</code> <a class="header-anchor" href="#b-go-run-main-go" aria-label="Permalink to &quot;B. `go run main.go`&quot;">​</a></h3><p><strong>&quot;Test Run&quot;</strong> This compiles your code in a temporary folder and runs it immediately. We use this 99% of the time while developing.</p><h3 id="c-go-build" tabindex="-1">C. <code>go build</code> <a class="header-anchor" href="#c-go-build" aria-label="Permalink to &quot;C. `go build`&quot;">​</a></h3><p><strong>&quot;Manufacture&quot;</strong> This creates a permanent binary file (executable). You can send this file to a friend, and they can run it <strong>without</strong> having Go installed!</p><hr><p><strong>Next</strong>: Now that the shop is open, let&#39;s learn how to read the blueprints.</p><details class="details custom-block"><summary>🎓 Knowledge Check: What command do we use to initialize a new Go module?</summary><p><strong>Answer</strong>: <code>go mod init &lt;module-name&gt;</code>. This creates the <code>go.mod</code> file, which is like the ID card for your project.</p></details><h2 id="_4-the-visual-signal-the-workbench" tabindex="-1">4 The Visual Signal (The Workbench) <a class="header-anchor" href="#_4-the-visual-signal-the-workbench" aria-label="Permalink to &quot;4 The Visual Signal (The Workbench)&quot;">​</a></h2><p><strong>Concept</strong>: Integrated Development Environment (IDE). <strong>Signal</strong>: A carpenter&#39;s workbench where all tools are within reach.</p>',22)),(o(),l(u,null,{default:t(()=>[d(a,{id:"mermaid-103",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20Workbench%5B%22%F0%9F%9B%A0%EF%B8%8F%20VS%20Code%20(The%20Workbench)%22%5D%0A%20%20%20%20%0A%20%20%20%20subgraph%20ToolsGraph%20%5BTools%5D%0A%20%20%20%20%20%20%20%20Hammer%5B%22%F0%9F%94%A8%20Go%20Compiler%20(Build)%22%5D%0A%20%20%20%20%20%20%20%20Ruler%5B%22%F0%9F%93%8F%20Linter%20(Format)%22%5D%0A%20%20%20%20%20%20%20%20Magnifier%5B%22%F0%9F%94%8D%20Delve%20(Debug)%22%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20Workbench%20--%3E%20Hammer%0A%20%20%20%20Workbench%20--%3E%20Ruler%0A%20%20%20%20Workbench%20--%3E%20Magnifier%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1}))])}const _=i(c,[["render",p]]);export{y as __pageData,_ as default};
